def get_input():
    import sys
    while True:
        try:
            n, m, q = map(int, input().split())
            if n == m == q == 0:
                break
            capacities = [tuple(map(int, input().split())) for _ in range(n-1)]
            edges_from_a_to_b = [tuple(map(int, input().split())) for _ in range(m)]
            change_inputs = []
            for _ in range(q):
                v, w = map(int, input().split())
                change_inputs.append((v, w))
            return n, m, q, capacities, edges_from_a_to_b, change_inputs
        except EOFError:
            break

def ford_fulkerson(graph, source, sink):
    n = len(graph)
    parent = [-1 for _ in range(n)]
    max_flow = 0
    while bfs(graph, parent, source, sink):
        flow = float('inf')
        s = sink
        while s != source:
            u = parent[s]
            flow = min(flow, graph[u][s][1])
            s = u
        s = sink
        while s != source:
            u = parent[s]
            graph[u][s][1] -= flow
            graph[s][u][1] += flow
            s = u
        max_flow += flow
    return max_flow

def bfs(graph, parent, source, sink):
    visited = [False for _ in range(len(graph))]
    queue = [[source]]
    while queue:
        current_path = queue.pop(0)
        u = current_path[-1]
        visited[u] = True
        for v, capacity, _ in reversed(graph[u]):
            if not visited[v] and capacity > 0:
                parent[v] = u
                queue.append(current_path + [v])
    return visited[sink]

def get_new_capacity(graph, index):
    if index + 1 == len(graph):
        return float('inf')
    return graph[index + 1][0][1]

def add_change(change, graph):
    changes = change
    for v, w in changes:
        if v < len(graph):
            graph[v][v][1] = min(get_new_capacity(graph, v), w)
            graph[v][v + 1][1] = float('inf')
            graph[v + 1][v][1] = 1000000000
            graph[v + 1][v + 1][1] = min(get_new_capacity(graph, v + 1), w - 1000000000)
        else:
            graph[-1][v][1] = min(get_new_capacity(graph, -1), w)
            graph[v - 1][v][1] = min(get_new_capacity(graph, v), w - 1000000000)
    return graph

