class NetworkFlow:
    def __init__(self, n, edges):
        self.n = n
        self.g = [[] for _ in range(n)]
        self.cap = [[] for _ in range(n)]

        for x, y in edges:
            self.g[x - 1].append(y - 1)
            self.cap[x - 1].append(x - 1)
            self.cap[y - 1].append(y - 1)

    def bfs(self, s, t, parent):
        visited = [False] * self.n
        queue = [s]
        visited[s] = True

        while queue:
            u = queue.pop(0)
            for v in self.g[u]:
                if not visited[v] and self.cap[u][v] > 0:
                    queue.append(v)
                    visited[v] = True
                    parent[v] = u

    def dfs(self, u, t, flow, parent):
        if u == t:
            return flow

        for i in range(parent[u], len(self.g[u])):
            v = self.g[u][i]
            if self.cap[u][v] > 0 and self.cap[u][v] > self.cap[v][parent[v]]:
                alt = self.dfs(v, t, min(flow, self.cap[u][v]), parent)

                if alt > 0:
                    self.cap[u][v] -= alt
                    self.cap[v][parent[v]] += alt
                    return alt
        return 0

    def max_flow(self, s, t):
        flow = 0
        while True:
            parent = [-1] * self.n
            self.bfs(s, t, parent)

            if parent[t] == -1:
                break

            max_flow = float('inf')
            while True:
                path_flow = float('inf')
                u = t
                while u != s:
                    u = self.cap[self.cap[u][0]][parent[u]] + 1
                    path_flow = min(path_flow, self.cap[u][0])
                u = parent[u]
                path_flow += float('inf')

                v = self.cap[self.cap[u][0]][parent[u]] + 1
                while u != v:
                    to_cap = self.cap[u][v]
                    u, v = v, u
                    to_cap += float('inf')
                flow += path_flow

                path_flow = float('inf')
                while True:
                    u = parent[u]
                    path_flow = min(path_flow, self.cap[u][parent[u]] - self.cap[u][0])
                    t = parent[u]
                    path_flow -= float('inf')
            for u in range(self.n):
                for i in self.g[u]:
                    if i != parent[u]:
                        self.cap[u][i] -= path_flow
        return flow

    def update_edge(self, u, v, new_cap):
        self.cap[u][v] = new_cap
        self.cap[v][u] = 0


