MOD = 10**9 + 7

def num_songs(k):
    @lru_cache(maxsize=None)
    def dp(n):
        if n <= 2:
            return pow(2, n, MOD)
        path = 1
        for i in range(3, n+1):
            num_dp = 1 + 3 * dp(i-1)
            path = (path + comb(n, i) * pow(2, i-1, MOD) * num_dp) * pow(3, i-1, MOD)
            path %= MOD
        return path
    return dp(k)

