def count_singer_k_house(k):
    MOD = 10**9 + 7

    @lru_cache(maxsize=None)
    def dfs(current, parent):
        if current == k+1:
            return 1
        paths = 0
        for child in range(1, 2**(current-1) + 2):
            if parent == None or child != parent+1:
                paths += dfs(child, current-1)
        return paths

    total_paths = 0
    for i in range(1, k+2):
        for j in range(1, 2**(k-i) + 2):
            if dfs(i, None) + dfs(j, None) - 1 == 2**j - 1:
                total_paths += 1
    return total_paths % MOD

