                min_prime = None
                for prime in range(2, int(sqrt(a[j])) + 1):
                    if a[j] % prime == 0:
                        while a[j] % prime == 0:
                            a[j] //= prime
                        min_d = min(min_d, prime)
                        if min_d == prime:
                            min_prime = prime
                if min_prime:
                    frac = a[j] * min_prime
                    new_min_d = sqrt(frac) * sqrt(frac)
                    a[j] = frac
                num_q = 3
                if new_d < num_q * a[j]:
                    new_tries.append(a.copy())
                new_tries.append(new_tries[-1])
        new_tries = new_tries[:-1]  
        tries = new_tries
    return len(tries)

def solve(a: List[int], queries: List[List[int]]) -> List[int]:
    result = []
    for l, r in queries:
        result.append(f(a[l-1:r]) - 1)
    return result

