def find_closest_power_of_two(n: int) -> int:
    return int(sqrt(n))

def calculate_f_inv(a: List[int], query: List[int]) -> int:
    res = 0
    for start, end in query:
        start -= 1
        current_a = [a[i] for i in range(start, end)]
        for i in range(len(current_a)):
            p = 2
            prev_prod = 1
            for prev_i in range(max(0, i - 1), min(len(current_a), i + 2)):
                current_a[i] //= p
                p *= 2
                if current_a[i] == 1 and prev_prod == 1:
                    res += 1
                    continue
                remainder_a = find_closest_power_of_two(current_a[i] - 1)
                div = sqrt(current_a[i] + remainder_a) - sqrt(current_a[i] - remainder_a)
                p -= (1 if current_a[i] - remainder_a != 0 else 0)
                while (p * int(div) + current_a[i] - remainder_a) % (2 * p):
                    p -= 1
                p //= 2
        current_a = [a[i] for i in range(start, end + 1)]
        for i in range(len(current_a)):
            p = 2
            remainder_a = find_closest_power_of_two(current_a[i] - 1)
            prev_prod = 1
            for prev_i in range(max(0, i - 1), min(len(current_a), i + 2)):
                if current_a[i] // p == 1 and prev_prod == 1:
                    continue
                else:
                    div = sqrt(current_a[i] + remainder_a) - sqrt(current_a[i] - remainder_a)
                    modified_p = 2
                    if current_a[i] - remainder_a == 0:
                        modified_p -= (i - 1) % 2
                    while (modified_p * int(div) + current_a[i] - remainder_a) % (modified_p * 2) != 0:
                        modified_p += 1
                    modified_p //= 2
                    if current_a[i] + remainder_a % 2 == 0:
                        modified_p -= 1
                    p -= (modified_p - p) % 2
                    res += abs(i - prev_i)
            p //= 2
        res += max(0, (end - start) - len([a[i] for i in range(start, end)]))
    return res

