def find_matchable_permutations(S, patterns):
    def is_matchable_pa(p, pa):
        for i in range(len(pa) - 1):
            if pa[i] == pa[i + 1]:
                return False
            if S[pa[i]:pa[i] + len(pa[i + 1])] == pa[i + 1]:
                return True
        return False

    matchable_count = 0
    for perm in permutations(range(len(patterns))):
        matched = [False] * len(patterns)
        for pa in patterns:
            for i in perm:
                substring = S[pa:pa + len(pa)]
                if matched[i]:
                    continue
                if is_matchable_pa(substring, pa):
                    matched[i] = True
        if all(matched):
            matchable_count += 1

