def f(a):
    memo = {}
    def dp(i, mask):
        if i == len(a):
            return 0
        if (i, mask) in memo:
            return memo[(i, mask)]
        if mask & (1 << i):
            return dp(i + 1, mask & ~(1 << i))
        choices = a[i]
        for p in range(2, 5032107 + 1):
            if is_square(choices * p):
                memo[(i, mask)] = min(dp(i + 1, mask | (1 << i)), dp(i + 1, mask))
                break
        else:
            memo[(i, mask)] = dp(i + 1, mask)
        return memo[(i, mask)]
    return dp(0, 0)

