from collections import deque

def F(n):
    seq = ['0', '1']
    for _ in range(2, n):
        seq.append(seq[-2] + seq[-1])
    return seq[n-1]

def A_F(n, k):
    sequence = deque(F(n))
    while k:
        if len(sequence) > k:
            k -= len(sequence)
            while len(sequence) > k:
                sequence.popleft()
        else:
            k -= len(sequence)
            break
    return ''.join(sequence)[:k]

