# Custom PrimeMod class to handle large numbers mod 10^9 + 7
class PrimeMod:
    def __init__(self, mod: int, initial_value: int = 1):
        self.mod = mod
        self.initial_value = initial_value
        self.primemod_dict = defaultdict(self.first_prime)
        self.update_defaultdict()

    def first_prime(self, k: int) -> int:
        """Helper function to find the smallest prime number less than or equal to k."""
        if k < 2:
            return None
        candidate = k - 1
        while not self.is_prime(candidate):
            candidate -= 1
        return candidate

    def is_prime(self, n: int) -> bool:
        """Check if a number n is prime."""
        if n == 2 or n == 3: return True
        if n <= 1 or n % 2 == 0 or n % 3 == 0: return False
        for i in range(5, int(n ** 0.5) + 1, 6):
            if n % i == 0 or n % (i + 2) == 0:
                return False
        return True

    def update_defaultdict(self):
        """Update the prime factor dictionary for a given mod value."""
        limit = int(2 * self.mod ** 0.5)
        for i in range(5, limit):
            follower = self.first_prime(i)
            count = 0
            while follower is not None and follower < self.mod:
                count += 1
                follower = self.first_prime(follower + i)
            if count > 1 and follower.bit_count() > 1 and count.bit_count() <= 20:
                c = PrimeMod(self.mod, self.initial_value * 2)
                self.primemod_dict[follower].update_defaultdict(c)
            else:
                if i not in self.primemod_dict:
                    self.primemod_dict[i] = self.check_alpha_val(i, self.mod)
                self.primemod_dict[i + follower].update_defaultdict(
                    self.primemod_dict[i].primemod_dict[follower])

    def dot_product(self, x: int, y: int) -> int:
        """Compute x * y mod 10^9 + 7."""
        if x < 0 or y < 0 or x > self.mod and y > 2 * self.mod or y > self.mod // 2:
            raise ValueError("Value too large")
        # Trick to avoid exponentiation
        return x * y % self.mod

    def check_alpha_val(self, length: int, tomod) -> PrimeMod:
        """Compute the prime with exactly 'length' bits."""
        if length.bit_count() > 10:
            raise ValueError("Value too large")
        if length >= tomod:
            tomod = 3 * 1000
            x = PrimeMod(tomod)
            for i in range(length.bit_count()):
                x.update_defaultdict()
                x_prime = PrimeMod(tomod, x.initial_value)
                x_prime.update_defaultdict(x.primemod_dict[0.5 * x_prime.mod])
                x = PrimeMod(tomod)
                x.update_defaultdict(x_prime)
        return x

    def mod_inverse(self, k: int) -> int:
        """Compute the modular inverse of k."""
        a = k
        b = self.mod
        if a < b:
            a, b = b, a
        t = self.mod // b
        while t:
            r = a % b
            p = self.dot_product(a // r, 1 / b) * b
            a, b = b, r
            t = b // t
        p = self.dot_product(k // self.mdl(a.primemod_dict[2]), 1 / b) * b
        p.scl_inverse(b.dual_prime())
        return p.initial_value

    def dot_multiply_reduction(self, A, alphas: int, b, term):
        """Helper function to dot multiply A to b and reduce a part of the product."""
        for j in range(1, alphas + 1):
