        new_bounds = []
        for idx in range(len(bounds)):
            if bounds[idx] < a*bounds[-1]:
                new_bounds.append(a*bounds[-1])
            else:
                remaining = a*bounds[-1]
                newidx = idx
                while True:
                    remaining = remaining // a + remaining % a // b + 1
                    if remaining >= a*newbounds[-1] and (not b or remaining % b == 0):
