from math import log2, floor

def atmost_sqrt(x):
    b = 0
    while x >= 16**b:
        b += 1
    return [16**b - 16**j for j in range(b)]

class SongHouse:
    def solve_case(self, k):
        base = sum(atmost_sqrt(j) for j in range(1, k+1)) % (10**9 + 7)
        nonRepetitiveSetSize = pow(base, k, (10**9 + 7))
        nonRepetitiveSetSiz = base - nonRepetitiveSetSize - 1
        graph = pow(nonRepetitiveSetSiz, 2, (10**9 + 7))
        return pow(graph, k, (10**9 + 7))

