from math import factorial
from typing import List

def count_matchable_permutations(n: int, m: int, patterns: List[str]) -> int:
    seen = {}
    for i in range(m):
        seen[i] = [0] * n

    for pattern in patterns:
        for i in range(len(pattern)):
            seen[i][ord(pattern[i]) - ord('a')] += 1

    result = 1
    for row in seen.values():
        result *= factorial(row).modinv(len(row) - 1)

    return result

# Example usage
if __name__ == "__main__":
    n, m = map(int, input().split())
    s = input()
    patterns = []
    for _ in range(m):
        patterns.append(input())

    print(count_matchable_permutations(n, m, patterns))
