from collections import OrderedDict

def count_probabilities(n, k, pi):
    probabilities = {i: 0 for i in range(1, n+1)}
    for i in range(n):
        cache_size = min(k, i+1) # The ceiling of (i+1)/k.
        probabilities[i+1] = cache_size / (i+1)

    for _ in range(10000000):
        last = 0
        for i in range(1, n):
            probabilities[i] = probabilities[i] * pi[i] / pi[last] + (1 - pi[i]) / (n-i+1)
            if probabilities[i] > 1:
                probabilities[i] = 1
            last = i

    return [round(probabilities[i] * 10**6) / 10**6 for i in range(1, n+1)]

n, k = map(int, input().split())
pi = list(map(float, input().split()))
print(' '.join(map(str, count_probabilities(n, k, pi))))
