from math import factorial

def count_paths(k):
    total_paths = 0
    mod = 10**9 + 7

    for i in range(1, k + 1):
        paths_in_layer = 1 << i
        paths_from_layer = 2 * (paths_in_layer - 1) // 2
        if i not in layers:
            paths_from_layer += 1 << (i - 1)
        total_paths = (total_paths + paths_in_layer * paths_from_layer) % mod

    return total_paths % mod

layers = [0]  # Initialize layers list for the first level of the graph.

for level in range(1, k + 1):
    for depth in range(1 << level):
        i = depth - 1 << (level - 1)
        layers.append(layers[i] + 2 * depth - 1)

for k_case in range(1, 410):
    print(f"Input: {k_case}\nOutput: {count_paths(k_case)}\n")
